    } else if (isArrowElement(original) && isArrowElement(duplicate)) {
      fixReversedBindingsForArrows(
        original,
        duplicate,
        originalElements,
        "startBinding",
        oldIdToDuplicatedId,
        elementsWithClones,
      );
      fixReversedBindingsForArrows(
        original,
        duplicate,
        originalElements,
        "endBinding",
        oldIdToDuplicatedId,
        elementsWithClones,
      );
    }
  }
};

