import {
  orderByFractionalIndex,
  syncInvalidIndices,
  syncMovedIndices,
  validateFractionalIndices,
} from "@excalidraw/element/fractionalIndex";

import { getSelectedElements } from "@excalidraw/element/selection";

import {
  mutateElement,
  type ElementUpdate,
