.excalidraw {
  &.theme--dark {
    .chat-message {
      &--assistant {
        .chat-message__content {
          background: var(--color-surface-lowest);
        }
      }

      &--system {
        .chat-message__content {
          color: var(--color-surface-low);
        }
      }
    }
  }

  .chat-interface {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
    position: relative;

    @media screen and (max-width: $verticalBreakpoint) {
      min-height: 200px;
    }

    &__messages {
      flex: 1 1 0;
      overflow-y: auto;
      margin-bottom: 0.5rem;
      padding: 1rem 0.5rem 0 0.5rem;
      display: flex;
      flex-direction: column;
      gap: 2rem;
      min-height: 0;
      border-top-left-radius: var(--border-radius-lg);
      border-top-right-radius: var(--border-radius-lg);

      @media screen and (max-width: $verticalBreakpoint) {
        min-height: 100px;
        padding: 0.75rem;
      }
    }

    &__empty-state {
      display: flex;
      align-items: center;
      justify-content: center;
      height: 100%;
      min-height: 200px;

      &-content {
        text-align: center;

        h3 {
          margin: 0 0 0.5rem 0;
          font-size: 1.25rem;
          font-weight: 600;
        }

        p {
          margin: 0 0 0.2rem 0;
          font-size: 0.875rem;
          color: var(--color-on-surface);
        }
      }

      @media screen and (max-width: $verticalBreakpoint) {
        min-height: 100px;
      }
    }

    &__input-outer {
      position: relative;
      min-height: 71px;
    }

    &__input-container {
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
    }

    &__input-wrapper {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;

      display: flex;
      align-items: flex-end;
      gap: 0.5rem;

      border: 1px solid var(--dialog-border-color);
      border-radius: var(--border-radius-lg);

      padding: 0.75rem;
      background: var(--color-surface-lowest);
      transition: border-color 0.2s ease;

      &:focus-within {
        border-color: var(--color-primary);
      }

      @media screen and (max-width: $verticalBreakpoint) {
        padding: 0.5rem 0.75rem;
      }
    }

    &__input {
      flex: 1;
      border: none;
      outline: none;
      font-size: 0.875rem;
      line-height: 1.5;
      min-height: 24px;
      max-height: 120px;
      overflow-x: hidden;
      border: none !important;
      background: transparent !important;
      color: var(--color-on-surface);

      &::placeholder {
        color: var(--color-gray-40);
      }

      @media screen and (max-width: $verticalBreakpoint) {
        line-height: 1.4;
        min-height: 20px;
        max-height: 100px;
        resize: none;
        padding: 0;

        &::placeholder {
          opacity: 0.6;
        }
      }
    }

    &__send-button {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 32px;
      height: 32px;
      border: none;
      border-radius: 50%;
      background: var(--color-primary);
      color: var(--color-surface-lowest);
      cursor: pointer;
      margin-bottom: 8px;

      &:disabled {
        opacity: 0.5;
        cursor: not-allowed;
        transform: none;
      }

      &:hover {
        background-color: var(--color-primary-darker);
      }

      svg {
        transform: rotate(-90deg);
      }
    }
  }

  .chat-message {
    display: flex;
    align-items: center;
    gap: 0.5rem;

    &--user {
      justify-content: flex-end;

      .chat-message__content {
        background: var(--color-primary-light);
        color: var(--text-primary-color);
        border-radius: var(--border-radius-md);
        min-width: 6rem;
      }
    }

    &--assistant {
      flex-direction: column;
      justify-content: flex-start;
      align-items: flex-start;

      .chat-message__content {
        background: var(--color-surface-low);
        color: var(--color-on-surface);
        border-radius: var(--border-radius-md);
        min-width: 6rem;

        .chat-message__body {
          font-family: monospace;
        }
      }
    }

    &--system {
      justify-content: flex-start;
      margin-bottom: 0;

      .chat-message__content {
        background: var(--color-warning);
        color: var(--color-on-surface);
        border-radius: var(--border-radius-md);
