      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      margin-bottom: 0.5rem;
      font-size: 0.75rem;
    }

    &__role {
      font-weight: 600;
    }

    &__timestamp {
      font-size: 0.625rem;
    }

    &__actions {
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    &__action {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      background: none;
      border: none;
      cursor: pointer;
      padding: 0.25rem 0;
      color: var(--color-gray-60);
      transition: color 0.2s ease;
      flex-shrink: 0;

      &.invisible {
        visibility: hidden;
        pointer-events: none;
      }

      &:hover {
        color: var(--color-primary);
      }

      svg {
        width: 14px;
        height: 14px;
      }
    }

    &__action--danger {
      &:hover {
        color: var(--color-danger);
      }
    }

    &__body {
      line-height: 1.5;
    }

    &__text {
      white-space: pre-wrap;
      word-wrap: break-word;
    }

    &__cursor {
      display: inline-block;
      margin-left: 2px;
      color: currentColor;
      animation: blink 1s infinite;
    }

    &__loading {
      display: flex;
      align-items: center;
      gap: 0.5rem;
