    if (Debug.DEBUG_LOG_INTERVAL_ID !== null) {
      Debug.ANIMATION_FRAME_ID = requestAnimationFrame((timestamp) => {
        if (Debug.LAST_FRAME_TIMESTAMP !== timestamp) {
          Debug.LAST_FRAME_TIMESTAMP = timestamp;
