    min-width: 2rem;
    min-height: 2rem;
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;

    .ToolIcon__icon {
      width: 2.25rem;
      height: 2.25rem;

      // hover has no meaning on touch devices (and sticks to the last-tapped
      // element), so suppress the hover background…
      &:hover {
        background-color: transparent;
      }
    }

    // …but not on checked buttons, where the sticky hover of the tap that
    // checked them would otherwise suppress the checked highlight
    &.ToolIcon--checked .ToolIcon__icon:hover {
