// top-picks drag & drop (pinning + reordering) — shared by the color and
// font pickers. Strips opt in via `.top-picks-dnd` + `.top-picks-dnd__pick`.
// -----------------------------------------------------------------------------

.excalidraw {
  .top-picks-dnd {
    // anchor for the animated drop-target outline
    position: relative;
  }

  .top-picks-dnd__pick {
    // the strip is tiny and never scrolls — allow touch-dragging picks
    touch-action: none;
  }

  .top-picks-dnd.is-dnd-active {
    .top-picks-dnd__pick {
      // no hover/tooltips while a drag is in flight; hit-testing is
      // coordinate-based so this doesn't affect dropping
      pointer-events: none;
      transition: transform 0.14s ease, opacity 0.14s ease,
        box-shadow 0.14s ease;
    }
  }

  .top-picks-dnd__outline {
    position: absolute;
    top: -5px;
    left: -5px;
    width: calc(100% + 10px);
    height: calc(100% + 10px);
    pointer-events: none;
    overflow: visible;

    rect {
      x: 0.5px;
      y: 0.5px;
      rx: 6px;
      width: calc(100% - 1px);
      height: calc(100% - 1px);
      fill: none;
      stroke: var(--color-primary);
      stroke-width: 1;
      stroke-dasharray: 4 4;
      animation: excalidraw-top-picks-dnd-march 0.8s linear infinite;

      @media (prefers-reduced-motion: reduce) {
        animation: none;
      }
    }
  }

  @keyframes excalidraw-top-picks-dnd-march {
    to {
      // one full dash+gap period per cycle → seamless loop
      stroke-dashoffset: -8;
    }
  }

  // the pick being reordered — its ghost is following the pointer
  .top-picks-dnd__pick.is-dnd-source {
    opacity: 0.3;
  }

  // this value is already pinned — drop not allowed
  .top-picks-dnd__pick.is-dnd-duplicate {
    animation: excalidraw-top-picks-dnd-duplicate 0.45s ease-in-out infinite
      alternate;
  }

  @keyframes excalidraw-top-picks-dnd-duplicate {
    from {
      box-shadow: 0 0 0 2px var(--color-danger, #e03131);
      transform: scale(1);
    }
    to {
      box-shadow: 0 0 0 3px var(--color-danger, #e03131);
      transform: scale(1.12);
    }
  }

  .top-picks-dnd__tip {
    padding: 0 0.5rem;
    font-size: 0.6875rem;
    line-height: 1.4;
    text-align: left;
    color: var(--color-gray-60);
  }

  // plain-text link
  .top-picks-dnd__tip-reset {
    padding: 0;
    margin: 0;
    border: 0;
    background: none;
    font: inherit;
    color: var(--color-primary);
    cursor: pointer;

    &:hover {
      text-decoration: underline;
    }
  }

  .top-picks-dnd__context-menu {
    background: var(--popup-bg-color);
    border-radius: var(--border-radius-lg);
    box-shadow: var(--shadow-island);
    padding: 0.25rem;
