    box-shadow: var(--top-picks-dnd-ghost-ring, 0 0 transparent);
    transition: transform 0.15s ease, opacity 0.15s ease, box-shadow 0.15s ease;
  }

  &--lifted &__content {
    transform: scale(1.2);
