        </div>
        <div className="file-drop-overlay__illustration" aria-hidden="true">
          {(["back", "front"] as const).map((position) => (
            <svg
              key={position}
              className={`file-drop-overlay__file file-drop-overlay__file--${position}`}
              viewBox="0 0 100 128"
              fill="none"
            >
              <path
